<script setup lang="ts">import {ref} from 'vue';import type {Snapshot,Utterance,User} from '../types/domain';import {snapshotApi} from '../api/snapshots';import {useAsync} from '../hooks/useAsync';import PageTitle from '../components/common/PageTitle.vue';import Table from '../components/common/Table.vue';import Notice from '../components/common/Notice.vue';const props=defineProps<{snapshots:Snapshot[];features:Record<string,string>;user:User;reload:()=>Promise<any>}>();const utterances=ref<Utterance[]>([]),showImport=ref(false),name=ref(''),kind=ref('candidate'),raw=ref('');const {task,act}=useAsync();async function submit(){await act(async()=>{await snapshotApi.create({name:name.value,kind:kind.value,filename:name.value+'.json',description:'研究员导入的匿名元特征',utterances:JSON.parse(raw.value)});await props.reload();showImport.value=false},'快照已导入')};</script><template><PageTitle index="02 / SOURCE MATERIAL" title="同一把标尺，始于两份来源。" description="匿名片段只保留时长、噪声、语速、语言与设备类别。缺失值进入独立桶，新类别与参考缺失分开计数。"><button v-if="user.role!=='viewer'" @click="showImport=!showImport">导入匿名快照 ↗</button></PageTitle><Notice :error="task.error" :message="task.message"/><form class="editor" v-if="showImport" @submit.prevent="submit"><h2>导入20–5000条JSON片段数组</h2><div class="form-grid"><label>快照名称<input v-model="name" maxlength="100" required/></label><label>快照用途<select v-model="kind"><option value="candidate">候选新增</option><option value="reference">参考冻结</option></select></label></div><label>片段JSON<textarea v-model="raw" rows="5" required placeholder='[{"reference":"NEW-001","features":{"duration":3.1,"noise":10,"token_rate":4.8,"language":"zh","device":"mobile"}},…]'/></label><p>五项特征完整；值可为null，保留桶名__NEW__/__MISSING__不可用作真实类别。</p><button class="primary" :disabled="task.busy">校验并导入</button></form><Table :headers="['快照 / 源文件','用途','片段数','说明','']"><tr v-for="s in snapshots" :key="s.id"><td><strong>{{s.name}}</strong><small>{{s.filename}}</small></td><td>{{s.kind==='reference'?'参考冻结':'候选新增'}}</td><td class="number">{{s.count}}</td><td class="description-cell">{{s.description}}</td><td><button class="text-button" @click="act(async()=>utterances=await snapshotApi.utterances(s.id),'')">查看前100片段 ↗</button></td></tr></Table><div class="source-principle"><b>来源检查</b><p>参考箱只从参考样本拟合；候选的极端值进入冻结尾箱，不改变边界。类别参考未出现的值进入新类别桶，null进入缺失桶。KS仅比较连续特征非缺失值，缺失比例由箱计数另行呈现。</p></div><template v-if="utterances.length"><div class="section-title"><h2>匿名元特征样本</h2><small>展示前{{utterances.length}}条；计算使用全量切片</small></div><Table :headers="['片段',...Object.values(features)]"><tr v-for="u in utterances" :key="u.id"><td class="mono">{{u.reference}}</td><td v-for="key in Object.keys(features)" :key="key">{{u.features[key]??'缺失'}}</td></tr></Table></template></template>
